import json, collections

CLUSTERS = ["mcp","workspace","pattern","distill","history","semantic","brief","seed","facts","memory","recall","retrieval","export","entities"]
def cluster(path):
    name = path.split("/")[-1]
    for c in CLUSTERS:
        if name.startswith(c): return c
    if name.startswith("manifest") or name.startswith("brain_manifest"): return "seed"
    return "core"

sym = {}
for line in open(".context/graph-symbols.ndjson"):
    r = json.loads(line)
    if r.get("record_type") != "symbol": continue
    fp = r.get("file_path","")
    if fp.startswith("internal/cli/") and fp.count("/")==2 and fp.endswith(".go"):
        sym[r["id"]] = fp

REL = {"CALLS","USES_TYPE","CONSTRUCTS","PARAM_TYPE","RETURNS_TYPE","READS_FIELD","WRITES_FIELD","ACCESSES","ASYNC_CALLS"}
mat = collections.Counter()   # (from_cluster,to_cluster) -> edges
pairsyms = collections.defaultdict(set)  # fan-out symbol sets
for line in open(".context/graph-edges.ndjson"):
    r = json.loads(line)
    if r.get("record_type") != "relation" or r.get("type") not in REL: continue
    f, t = sym.get(r["from_id"]), sym.get(r["to_id"])
    if not f or not t: continue
    cf, ct = cluster(f), cluster(t)
    if cf != ct:
        mat[(cf,ct)] += 1
        pairsyms[(cf,ct)].add(r["to_id"])

def istest(p): return p.endswith("_test.go")
# per-cluster: files, test files, fan-out distinct symbols (to core+others), fan-in distinct symbols (referenced from outside), split prod/test source
rows = {}
for c in set(cluster(f) for f in set(sym.values())):
    fanout = sum(len(pairsyms[(c,o)]) for o in CLUSTERS+["core"] if o!=c)
    fanin  = sum(len(pairsyms[(o,c)]) for o in CLUSTERS+["core"] if o!=c)
    files = {f for f in set(sym.values()) if cluster(f)==c}
    rows[c] = (len([f for f in files if not istest(f)]), len([f for f in files if istest(f)]), fanout, fanin)
print(f"{'cluster':12} {'src':>4} {'test':>4} {'fanout(distinct syms used elsewhere)':>8} {'fanin(distinct syms others use)':>8}")
for c,(s,t,fo,fi) in sorted(rows.items(), key=lambda kv: kv[1][2]+kv[1][3]):
    print(f"{c:12} {s:4} {t:4} {fo:8} {fi:8}")
EOF

